macro_rules! mtime_recursive {
    () => {
        # [doc = " Returns the maximum mtime of the given path, recursing into"] # [doc = " subdirectories, and following symlinks."] pub fn mtime_recursive (path : & Path) -> Result < FileTime > { let meta = metadata (path) ? ; if ! meta . is_dir () { return Ok (FileTime :: from_last_modification_time (& meta)) ; } let max_meta = walkdir :: WalkDir :: new (path) . follow_links (true) . into_iter () . filter_map (| e | match e { Ok (e) => Some (e) , Err (e) => { tracing :: debug ! ("failed to determine mtime while walking directory: {}" , e) ; None } }) . filter_map (| e | { if e . path_is_symlink () { let sym_meta = match std :: fs :: symlink_metadata (e . path ()) { Ok (m) => m , Err (err) => { tracing :: debug ! ("failed to determine mtime while fetching symlink metadata of {}: {}" , e . path () . display () , err) ; return None ; } } ; let sym_mtime = FileTime :: from_last_modification_time (& sym_meta) ; match e . metadata () { Ok (target_meta) => { let target_mtime = FileTime :: from_last_modification_time (& target_meta) ; Some (sym_mtime . max (target_mtime)) } Err (err) => { tracing :: debug ! ("failed to determine mtime of symlink target for {}: {}" , e . path () . display () , err) ; Some (sym_mtime) } } } else { let meta = match e . metadata () { Ok (m) => m , Err (err) => { tracing :: debug ! ("failed to determine mtime while fetching metadata of {}: {}" , e . path () . display () , err) ; return None ; } } ; Some (FileTime :: from_last_modification_time (& meta)) } }) . max () . unwrap_or_else (| | FileTime :: from_last_modification_time (& meta)) ; Ok (max_meta) }
    };
}

mtime_recursive!();